// Local source-inspection witness only; synthetic Chat leaf, no AI/governance claim.
import { useEffect } from 'react';
import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import DashboardLayout from './layout';
const { delivered } = vi.hoisted(() => ({ delivered: vi.fn() }));
vi.mock('next/navigation', () => ({ usePathname: () => '/home', useRouter: () => ({ push: vi.fn(), replace: vi.fn() }), useSearchParams: () => ({ get: () => null, toString: () => '' }) }));
vi.mock('@/lib/hooks/useAuth', () => ({ useAuth: () => ({ userRole: 'admin', userName: 'Fixture', permissions: {}, handleLogout: vi.fn(), impersonation: null, endImpersonation: vi.fn() }) }));
vi.mock('@/lib/hooks/useModals', () => ({ useModals: () => ({ closeAllModals: vi.fn(), openModal: vi.fn(), closeModal: vi.fn() }) }));
vi.mock('@/lib/store', () => ({ useExecutionStore: () => ({ executions: [] }) }));
vi.mock('@/components/Settings', () => ({ useSettings: () => ({ settings: { providers: {}, preferences: { defaultProvider: 'alibaba' } }, updateProvider: vi.fn(), updatePreferences: vi.fn() }) }));
vi.mock('@/lib/i18n', () => ({ useLanguage: () => ({ language: 'en', t: (s: string) => s }) }));
vi.mock('@/components/CompactHeader', () => ({ default: () => null }));
vi.mock('@/components', async () => ({
    AgentChatWithHistory: (await import('@/components/AgentChatWithHistory')).AgentChatWithHistory,
    Sidebar: () => null, OnboardingWizard: () => null, QuickStart: () => null,
    UserContextForm: () => null, SettingsPage: () => null, AIUsagePanel: () => null,
    ApiKeyWizard: () => null, MultiAgentPanel: () => null, ToolsPage: () => null,
}));
vi.mock('@/components/AgentChat', () => ({
    AgentChat: ({ initialPrompt, onMessagesChange, onMinimize }: {
        initialPrompt?: string; onMessagesChange: (v: unknown[]) => void; onMinimize: () => void;
    }) => {
        useEffect(() => {
            if (initialPrompt) {
                delivered(initialPrompt);
                onMessagesChange([{ id: `fixture-${initialPrompt}`, role: 'user', content: initialPrompt, timestamp: new Date() }]);
            }
        }, [initialPrompt, onMessagesChange]);
        return <button onClick={onMinimize}>Witness minimize</button>;
    },
}));
vi.mock('@/lib/chat-history', async original => ({
    ...await original<typeof import('@/lib/chat-history')>(), ChatHistorySidebar: () => null,
}));
const handoff = (prompt: string) => act(() => { window.dispatchEvent(new CustomEvent('cvf:openAgent', { detail: { prompt } })); });
describe('Local incoming handoff lifecycle witness', () => {
    beforeEach(() => { localStorage.clear(); delivered.mockClear(); });
    afterEach(() => { cleanup(); localStorage.clear(); });
    it('minimize/restore preserves one delivery and one existing history session', async () => {
        render(<DashboardLayout><div>Home witness</div></DashboardLayout>);
        handoff('LOCAL_CURRENT_A');
        expect(delivered.mock.calls.map(c => c[0])).toEqual(['LOCAL_CURRENT_A']);
        const first = JSON.parse(localStorage.getItem('cvf_chat_history')!);
        fireEvent.click(screen.getByText('Witness minimize'));
        fireEvent.click(screen.getByText('CVF Agent'));
        expect(delivered.mock.calls.map(c => c[0])).toEqual(['LOCAL_CURRENT_A']);
        expect(JSON.parse(localStorage.getItem('cvf_chat_history')!).sessions.map((s: { id: string }) => s.id))
            .toEqual(first.sessions.map((s: { id: string }) => s.id));
    });
    it('new handoff B while chat A is open receives B in a distinct session', async () => {
        render(<DashboardLayout><div>Home witness</div></DashboardLayout>);
        handoff('LOCAL_CURRENT_A');
        handoff('LOCAL_CURRENT_B');
        expect(delivered.mock.calls.map(c => c[0])).toEqual(['LOCAL_CURRENT_A', 'LOCAL_CURRENT_B']);
        const history = JSON.parse(localStorage.getItem('cvf_chat_history')!);
        expect(history.sessions).toHaveLength(2);
        const active = history.sessions.find((s: { id: string }) => s.id === history.activeSessionId);
        expect(active.messages.map((m: { content: string }) => m.content)).toEqual(['LOCAL_CURRENT_B']);
    });
});
